$t['Automatic setup creates the webhook for this site URL only, or adds the missing events to it and keeps any other events. It saves the Webhook ID used to verify signatures. It never deletes webhooks, never touches other URLs and never changes the app permissions.'] = 'La configuración automática crea el webhook solo para la URL de este sitio, o le añade los eventos que faltan y conserva los demás eventos. Guarda el ID del webhook usado para verificar las firmas. Nunca elimina webhooks, nunca modifica otras URL y nunca cambia los permisos de la aplicación.';
$t['Automatic setup needs Webhook Endpoints: Write. It creates the webhook and securely saves its new signing secret, or enables the existing endpoint and adds missing events. It preserves existing events and does not replace endpoints or change API key permissions.'] = 'La configuración automática necesita Webhook Endpoints: Write. Crea el webhook y guarda de forma segura su nuevo secreto de firma, o habilita el endpoint existente y añade los eventos que faltan. Conserva los eventos existentes y no reemplaza endpoints ni cambia los permisos de la clave de API.';
