$t['Final test: complete a sandbox purchase, confirm an HTTP 200 delivery in Stripe, then check the wallet or rental, subscription access and video playback. Also test a declined card and 3D Secure. Never retry a charged payment just because access is still pending.'] = 'Prueba final: completa una compra en sandbox, confirma una entrega HTTP 200 en Stripe y luego verifica la billetera o el alquiler, el acceso a la suscripción y la reproducción del video. Prueba también una tarjeta rechazada y 3D Secure. Nunca reintentes un pago ya cobrado solo porque el acceso siga pendiente.';
$t['Final test: complete a sandbox purchase with a Personal sandbox buyer, confirm an HTTP 200 webhook delivery in developer.paypal.com, then check the wallet, rental, subscription and video playback. Never retry a paid purchase just because access is still pending.'] = 'Prueba final: completa una compra en sandbox con un comprador sandbox Personal, confirma una entrega del webhook con HTTP 200 en developer.paypal.com y luego verifica la billetera, el alquiler, la suscripción y la reproducción del video. Nunca reintentes una compra pagada solo porque el acceso siga pendiente.';
