$t['The connection to the destination was dropped mid-stream. This may be a temporary network issue; FFMPEG will try to reconnect.'] = 'La conexión con el destino se cortó durante la transmisión. Puede ser un problema temporal de red; FFMPEG intentará reconectarse.';
