$t['The daily YouTube upload quota of this website was reached. Uploads become available again after midnight Pacific Time. Please try again later.'] = 'Se alcanzó la cuota diaria de subidas a YouTube de este sitio web. Las subidas volverán a estar disponibles después de la medianoche, hora del Pacífico. Inténtalo de nuevo más tarde.';
$t['The database version changes only when a database migration is applied. It is not expected to match the release tag or commit.'] = 'La versión de la base de datos solo cambia cuando se aplica una migración de la base de datos. No se espera que coincida con la etiqueta de la versión ni con el commit.';
