$t['The selected position is outlined on a real page of your site and follows the position you choose below. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'La posición seleccionada se resalta en una página real de tu sitio y sigue la posición que elijas abajo. La vista previa móvil solo cambia las posiciones de los anuncios; el resto de la página usa el dispositivo de tu navegador.';
$t['The site is currently offline due to a database issue. We are working to resolve the problem as quickly as possible.'] = 'El sitio está fuera de línea debido a un problema con la base de datos. Estamos trabajando para resolverlo lo antes posible.';
$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = 'El sitio no está disponible temporalmente porque el disco del servidor está lleno. Estamos trabajando en ello y volveremos en breve.';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = 'El sitio está en mantenimiento porque el disco del servidor está casi lleno. Estamos solucionando el problema y volveremos en breve.';
$t['The site refused access. Renew the encoder account access and check its upload permissions.'] = 'El sitio denegó el acceso. Renueva el acceso de la cuenta del codificador y comprueba sus permisos de subida.';
