$t['The stream has timestamp discontinuities. This can cause buffering or playback issues on the destination platform.'] = 'La transmisión tiene discontinuidades en las marcas de tiempo. Esto puede causar almacenamiento en búfer o problemas de reproducción en la plataforma de destino.';
